@layer moduix.components {
  .root {
    display: inline-flex;
    align-items: center;
    max-inline-size: 100%;
    gap: var(--moduix-pagination-gap, var(--moduix-spacing-1));
    overflow-x: auto;
    color: var(--moduix-pagination-color, var(--moduix-color-foreground));
  }

  .item,
  .trigger,
  .ellipsis {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--moduix-pagination-item-size, var(--moduix-size-md));
    height: var(--moduix-pagination-item-size, var(--moduix-size-md));
    border-radius: var(--moduix-pagination-item-radius, var(--moduix-radius-md));
    font-size: var(--moduix-pagination-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-pagination-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-pagination-line-height, var(--moduix-line-height-text-sm));
    font-variant-numeric: tabular-nums;
  }

  .item,
  .trigger {
    cursor: pointer;
    gap: var(--moduix-pagination-trigger-gap, var(--moduix-spacing-2));
    border: var(--moduix-pagination-item-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-pagination-item-border-color, var(--moduix-color-border));
    padding-inline: var(--moduix-pagination-item-padding-inline, var(--moduix-spacing-2));
    background-color: var(--moduix-pagination-item-bg, var(--moduix-color-background));
    color: var(--moduix-pagination-item-color, var(--moduix-color-foreground));
    font-family: inherit;
    text-decoration: none;
    user-select: none;
    white-space: nowrap;

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-pagination-item-bg-hover, var(--moduix-color-accent));
      }
    }

    &:focus-visible {
      outline: var(
          --moduix-pagination-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-pagination-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(
        --moduix-pagination-focus-ring-offset,
        var(--moduix-focus-ring-inset-offset)
      );
    }

    &:is([data-disabled], :disabled) {
      opacity: var(--moduix-pagination-disabled-opacity, var(--moduix-opacity-disabled));
      pointer-events: none;
    }

    & svg {
      flex-shrink: 0;
      width: var(--moduix-pagination-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-pagination-icon-size, var(--moduix-spacing-4));
    }
  }

  .item[data-selected] {
    border-color: var(
      --moduix-pagination-item-border-color-selected,
      var(--moduix-color-foreground)
    );
    background-color: var(--moduix-pagination-item-bg-selected, var(--moduix-color-foreground));
    color: var(--moduix-pagination-item-color-selected, var(--moduix-color-background));

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-pagination-item-bg-selected, var(--moduix-color-foreground));
      }
    }
  }

  .trigger {
    padding-inline: max(
      var(--moduix-pagination-item-padding-inline, var(--moduix-spacing-2)),
      var(--moduix-spacing-3)
    );
  }

  .iconTrigger {
    width: var(--moduix-pagination-item-size, var(--moduix-size-md));
    padding-inline: 0;
  }

  .iconTrigger:dir(rtl) svg {
    transform: scaleX(-1);
  }

  .ellipsis {
    color: var(--moduix-pagination-ellipsis-color, var(--moduix-color-muted-foreground));
    user-select: none;
  }

  .edgeIcon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    & svg + svg {
      margin-inline-start: calc(var(--moduix-pagination-icon-size, var(--moduix-spacing-4)) * -0.5);
    }
  }
}

import { PaginationContext, usePagination, usePaginationContext } from '@ark-ui/vue/pagination';
import Pagination from './Pagination.vue';
import PaginationEllipsis from './PaginationEllipsis.vue';
import PaginationFirstTrigger from './PaginationFirstTrigger.vue';
import PaginationItem from './PaginationItem.vue';
import PaginationItems from './PaginationItems.vue';
import PaginationLastTrigger from './PaginationLastTrigger.vue';
import PaginationNextTrigger from './PaginationNextTrigger.vue';
import PaginationPrevTrigger from './PaginationPrevTrigger.vue';
import PaginationRootProvider from './PaginationRootProvider.vue';

export {
  Pagination,
  PaginationContext,
  PaginationEllipsis,
  PaginationFirstTrigger,
  PaginationItem,
  PaginationItems,
  PaginationLastTrigger,
  PaginationNextTrigger,
  PaginationPrevTrigger,
  PaginationRootProvider,
  usePagination,
  usePaginationContext,
};

export type {
  PaginationContextProps,
  PaginationEllipsisProps,
  PaginationFirstTriggerProps,
  PaginationItemLabelDetails,
  PaginationItemProps,
  PaginationLastTriggerProps,
  PaginationNextTriggerProps,
  PaginationPageChangeDetails,
  PaginationPageSizeChangeDetails,
  PaginationPageUrlDetails,
  PaginationPrevTriggerProps,
  PaginationRootEmits,
  PaginationRootProps,
  PaginationRootProviderProps,
  UsePaginationContext,
  UsePaginationProps,
  UsePaginationReturn,
} from '@ark-ui/vue/pagination';
